// W2 step 1 – Recfluence channels: parse, filter, clean, batch
// Mode: Run Once for All Items.
// Input: output of an 'Extract from File' node (operation: Extract From Text File), i.e. the file text in $json.data.
// Written without Buffer/this.helpers so it runs in n8n's sandboxed task runner.

const MIN_SUBS = 100000;
const BATCH_SIZE = 5000;   // one request: parallel batches deadlocked on shared nodes (see notes)

// Channels from the Lewis network, always imported even below the filter
const LEWIS_IDS = new Set([
  'UC-yewGHQbNFpDrGM0diZOLA','UC0aVoboXBUx2-tVIWHc3W2Q','UC0rZoXAD5lxgBHMsjrGwWWQ','UC2h3yPmh9TfQv2z3aTDTHHA',
