// Repair text that was UTF-8 but got decoded as Windows-1252 ("GariÃ©py" -> "Gariépy")
const CP1252 = {0x20AC:0x80,0x201A:0x82,0x0192:0x83,0x201E:0x84,0x2026:0x85,0x2020:0x86,0x2021:0x87,0x02C6:0x88,
  0x2030:0x89,0x0160:0x8A,0x2039:0x8B,0x0152:0x8C,0x017D:0x8E,0x2018:0x91,0x2019:0x92,0x201C:0x93,0x201D:0x94,
  0x2022:0x95,0x2013:0x96,0x2014:0x97,0x02DC:0x98,0x2122:0x99,0x0161:0x9A,0x203A:0x9B,0x0153:0x9C,0x017E:0x9E,0x0178:0x9F};
function utf8Decode(bytes) {
  // returns null if the bytes are not valid UTF-8
  let out = '', i = 0;
  while (i < bytes.length) {
    const b = bytes[i];
    let cp, n;
    if (b < 0x80) { cp = b; n = 0; }
    else if (b >= 0xC2 && b < 0xE0) { cp = b & 0x1F; n = 1; }
    else if (b >= 0xE0 && b < 0xF0) { cp = b & 0x0F; n = 2; }
    else if (b >= 0xF0 && b < 0xF5) { cp = b & 0x07; n = 3; }
    else return null;
    if (i + n >= bytes.length + (n ? 0 : 1)) return null;
    for (let k = 1; k <= n; k++) {
      const c = bytes[i + k];
      if (c === undefined || (c & 0xC0) !== 0x80) return null;
      cp = (cp << 6) | (c & 0x3F);
    }
    out += String.fromCodePoint(cp);
    i += n + 1;
  }
  return out;
}
function decodeRun(run) {
  const bytes = [];
  for (const ch of run) {
    const c = ch.codePointAt(0);
    bytes.push(c < 0x100 ? c : CP1252[c]);
  }
  const out = utf8Decode(bytes);
  return out === null ? run : out;   // only accept a clean repair
}
function fixText(s) {
  if (!s || !/[ÃÂâ]/.test(s)) return s;
  s = s.replace(/Â(?=\s)/g, '');        // "Â " is a mangled non-breaking space
  // repair each run of suspicious characters separately, so one bad spot can't block the rest
  const cp = Object.keys(CP1252).map(k => String.fromCodePoint(+k)).join('');
  return s.replace(new RegExp(`[\u0080-\u00FF${cp}]+`, 'gu'), decodeRun);
}

const LEAN = { L: 'left', C: 'centre', R: 'right' };

const text = $input.first().json.data;
if (typeof text !== 'string') {
  throw new Error('Expected the file text in $json.data – put an "Extract from File" node (Extract From Text File) before this node.');
}
const lines = text.split('\n').filter(l => l.trim());

const rows = [];
for (const line of lines) {
  const r = JSON.parse(line);
  const keep = (r.reviewsHuman >= 1 && r.subs >= MIN_SUBS) || LEWIS_IDS.has(r.channelId);
  if (!keep) continue;
  rows.push({
    channelId: r.channelId,
    title: fixText(r.channelTitle),
    subs: r.subs,
    views: r.channelViews,
    lean: LEAN[r.lr] ?? null,
    humanReviews: r.reviewsHuman,
    labelSource: r.reviewsHuman >= 1 ? 'human' : 'auto',
    tags: r.tags ?? [],
    description: fixText(r.description) || null,
    reviewerNote: r.publicReviewerNotes,
    creatorNote: r.publicCreatorNotes,
    inLewis: LEWIS_IDS.has(r.channelId),
  });
}

const CYPHER = `
UNWIND $rows AS r
MERGE (c:Channel {channelId: r.channelId})
SET c.title = r.title, c.subs = r.subs, c.views = r.views,
    c.lean = r.lean, c.humanReviews = r.humanReviews,
    c.labelSource = r.labelSource, c.description = r.description,
    c.reviewerNote = r.reviewerNote, c.creatorNote = r.creatorNote,
    c.inLewis = r.inLewis, c.source = 'Recfluence'
WITH c, r
UNWIND r.tags AS t
MATCH (tag:Tag {name: t})            // tags are created by W1, so batches never fight over them
MERGE (c)-[:TAGGED_AS {source: 'Recfluence'}]->(tag)`;

// One output item per batch; the HTTP Request node sends $json.body to Neo4j's Query API
const out = [];
for (let i = 0; i < rows.length; i += BATCH_SIZE) {
  const batch = rows.slice(i, i + BATCH_SIZE);
  out.push({ json: {
    batch: out.length + 1,
    count: batch.length,
    body: { statement: CYPHER, parameters: { rows: batch } },
  } });
}
return out;

// W2 step 2 – Lewis people. Mode: Run Once for All Items.
// Input: rows from lewis_people.csv (Extract from File → CSV).
const rows = $input.all().map(({ json: r }) => ({
  id: r.person_id,
  name: r.name,
  figureLabel: r.figure_label || null,
  inFigure: r.in_figure === 'true',
  show: r.show || null,
}));

const statement = `
UNWIND $rows AS r
MERGE (p:Person {id: r.id})
SET p.name = r.name, p.figureLabel = r.figureLabel, p.inFigure = r.inFigure,
    p.show = r.show, p.source = 'Lewis 2018, Appendix B'`;

return [{ json: { step: 'People', count: rows.length, body: { statement, parameters: { rows } } } }];

// W2 step 3 – Person -[:RUNS]-> Channel. Mode: Run Once for All Items.
// Input: rows from lewis_channels.csv (Extract from File → CSV).
// Channels Lewis lists but Recfluence doesn't have are stored on the Person as a list, so the agent can mention them.
const all = $input.all().map(i => i.json);

const runs = all.filter(r => r.recfluence_channel_id).map(r => ({
  personId: r.person_id,
  channelId: r.recfluence_channel_id,
  lewisName: r.lewis_channel_name,
  listedByLewis: r.listed_by_lewis === 'true',
  note: r.note || null,
}));

const unmatched = {};
for (const r of all.filter(r => !r.recfluence_channel_id && r.lewis_channel_name)) {
  (unmatched[r.person_id] ??= []).push(r.lewis_channel_name);
}
const missing = Object.entries(unmatched).map(([personId, names]) => ({ personId, names }));

// One request for both parts: two parallel requests touching the same Person nodes can deadlock.
const statement = `
UNWIND $runs AS r
MATCH (p:Person {id: r.personId})
MATCH (c:Channel {channelId: r.channelId})
MERGE (p)-[x:RUNS]->(c)
SET x.lewisChannelName = r.lewisName, x.listedByLewis = r.listedByLewis,
    x.note = r.note, x.source = 'Lewis 2018, Appendix B'
WITH count(x) AS runsWritten
CALL () {
  UNWIND $missing AS m
  MATCH (p:Person {id: m.personId})
  SET p.channelsNotInRecfluence = m.names
  RETURN count(p) AS peopleWithMissingChannels
}
RETURN runsWritten, peopleWithMissingChannels`;

return [{ json: { step: 'RUNS', count: runs.length, body: { statement, parameters: { runs, missing } } } }];

// W2 step 4 – Person -[:APPEARED_WITH]- Person. Mode: Run Once for All Items.
// Input: rows from lewis_edges.csv (Extract from File → CSV).
const BATCH_SIZE = 5000;   // one request: parallel batches deadlocked on shared nodes (see notes)
const num = v => (v === '' || v == null ? null : Number(v));

const rows = $input.all().map(({ json: r }) => ({
  a: r.a,
  b: r.b,
  confidence: r.confidence,            // high | medium | check
  fromFigure: r.from_figure === 'true',
  pixelCoverage: num(r.pixel_coverage),
  pixelRidge: num(r.pixel_ridge),
  note: r.note || null,
  evidence: r.evidence ? r.evidence.split(' | ') : [],
}));

const statement = `
UNWIND $rows AS r
MATCH (a:Person {id: r.a})
MATCH (b:Person {id: r.b})
MERGE (a)-[e:APPEARED_WITH]-(b)
SET e.confidence = r.confidence, e.fromFigure = r.fromFigure,
    e.pixelCoverage = r.pixelCoverage, e.pixelRidge = r.pixelRidge,
    e.note = r.note, e.evidence = r.evidence,
    e.source = 'Lewis 2018, Fig. 1', e.periodStart = date('2017-01-01'), e.periodEnd = date('2018-04-01')
RETURN count(e) AS written`;

const out = [];
for (let i = 0; i < rows.length; i += BATCH_SIZE) {
  const batch = rows.slice(i, i + BATCH_SIZE);
  out.push({ json: { step: 'APPEARED_WITH', batch: out.length + 1, count: batch.length, body: { statement, parameters: { rows: batch } } } });
}
return out;

// Fail loudly if Neo4j reports an error. Covers both cases: an HTTP error status
// (the node fails by itself) and a 2xx response with an "errors" list in the body.
for (const item of $input.all()) {
  const errors = item.json.errors ?? [];
  if (errors.length) {
    throw new Error(`Neo4j error: ${errors[0].code} – ${errors[0].message}`);
  }
}
return $input.all();

